using System.Security.Claims;using CampusPlacementManagement.Data;using CampusPlacementManagement.DTOs.Interviews;using CampusPlacementManagement.Models;using CampusPlacementManagement.Models.Enums;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace CampusPlacementManagement.Controllers;
[ApiController,Route("api"),Authorize]
public class InterviewsController:ControllerBase
{private readonly ApplicationDbContext _db;public InterviewsController(ApplicationDbContext db)=>_db=db;private string Uid()=>User.FindFirstValue(ClaimTypes.NameIdentifier)!;
[Authorize(Roles="CompanyHR"),HttpPost("jobs/{jobId}/interview-rounds")]public async Task<IActionResult> Round(int jobId,CreateInterviewRoundDto d){var hr=await _db.CompanyHRs.FirstOrDefaultAsync(x=>x.UserId==Uid());if(hr==null||!await _db.Jobs.AnyAsync(x=>x.JobId==jobId&&x.CreatedByHRId==hr.CompanyHRId))return Forbid();var r=new InterviewRound{JobId=jobId,RoundName=d.RoundName,RoundNumber=d.RoundNumber,Description=d.Description};await _db.InterviewRounds.AddAsync(r);await _db.SaveChangesAsync();return Ok(r);}
[HttpGet("jobs/{jobId}/interview-rounds")]public async Task<IActionResult> Rounds(int jobId)=>Ok(await _db.InterviewRounds.Include(x=>x.Schedules).Where(x=>x.JobId==jobId).AsNoTracking().OrderBy(x=>x.RoundNumber).ToListAsync());
[Authorize(Roles="CompanyHR"),HttpPost("applications/{applicationId}/interviews")]public async Task<IActionResult> Schedule(int applicationId,CreateInterviewScheduleDto d){var hr=await _db.CompanyHRs.FirstOrDefaultAsync(x=>x.UserId==Uid());var a=await _db.JobApplications.Include(x=>x.Job).FirstOrDefaultAsync(x=>x.ApplicationId==applicationId);if(hr==null||a==null||a.Job.CreatedByHRId!=hr.CompanyHRId)return Forbid();if(!await _db.InterviewRounds.AnyAsync(x=>x.InterviewRoundId==d.InterviewRoundId&&x.JobId==a.JobId))throw new InvalidOperationException("Interview round does not belong to the application job.");var i=new InterviewSchedule{ApplicationId=applicationId,InterviewRoundId=d.InterviewRoundId,ScheduledAt=d.ScheduledAt,MeetingLink=d.MeetingLink,Venue=d.Venue};await _db.InterviewSchedules.AddAsync(i);a.Status=ApplicationStatus.InterviewScheduled;a.LastUpdatedAt=DateTime.UtcNow;await _db.ApplicationStatusHistories.AddAsync(new ApplicationStatusHistory{ApplicationId=a.ApplicationId,PreviousStatus=a.Status,NewStatus=ApplicationStatus.InterviewScheduled,UpdatedByUserId=Uid(),Remarks="Interview scheduled."});await _db.SaveChangesAsync();return Ok(i);}
[HttpGet("applications/{applicationId}/interviews")]public async Task<IActionResult> Schedules(int applicationId)=>Ok(await _db.InterviewSchedules.Include(x=>x.InterviewRound).Where(x=>x.ApplicationId==applicationId).AsNoTracking().ToListAsync());
[Authorize(Roles="CompanyHR"),HttpPut("interviews/{id}")]public async Task<IActionResult> Update(int id,UpdateInterviewDto d){var i=await _db.InterviewSchedules.Include(x=>x.Application).ThenInclude(x=>x.Job).FirstOrDefaultAsync(x=>x.InterviewScheduleId==id);var hr=await _db.CompanyHRs.FirstOrDefaultAsync(x=>x.UserId==Uid());if(i==null||hr==null||i.Application.Job.CreatedByHRId!=hr.CompanyHRId)return Forbid();i.ScheduledAt=d.ScheduledAt;i.MeetingLink=d.MeetingLink;i.Venue=d.Venue;i.Status=InterviewStatus.Rescheduled;await _db.SaveChangesAsync();return Ok(i);}
[Authorize(Roles="CompanyHR"),HttpPut("interviews/{id}/feedback")]public async Task<IActionResult> Feedback(int id,InterviewFeedbackDto d){var i=await _db.InterviewSchedules.Include(x=>x.Application).ThenInclude(x=>x.Job).FirstOrDefaultAsync(x=>x.InterviewScheduleId==id);var hr=await _db.CompanyHRs.FirstOrDefaultAsync(x=>x.UserId==Uid());if(i==null||hr==null||i.Application.Job.CreatedByHRId!=hr.CompanyHRId)return Forbid();i.Feedback=d.Feedback;i.Status=InterviewStatus.Completed;await _db.SaveChangesAsync();return Ok(i);}}
